result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "payments_app.py", "content": """"
Payments API with idempotency keys (FastAPI + SQLite).

POST /payments
  - Header `Idempotency-Key` required.
  - First call: executes payment, stores (key, body_hash, response).
  - Same key + same body: replays stored response with `Idempotent-Replay: true`,
    no second payment row.
  - Same key + different body: 422 {"error": {"code": "idempotency_conflict"}}.

Concurrency strategy: "INSERT to win, losers wait-and-replay".
The idempotency_keys.key PRIMARY KEY is the serialization point. Exactly one
request wins the INSERT ("owner") and executes; all others poll until the
owner commits the stored response, then replay it. A UNIQUE constraint on
payments.idempotency_key is defense-in-depth at the DB level.
"""

import hashlib
import json
import os
import sqlite3
import time
import uuid

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

app = FastAPI()

# Read lazily so tests can point each server instance at its own DB file.
def db_path() -> str:
    return os.environ.get("PAYMENTS_DB", "payments.db")

POLL_INTERVAL = 0.02   # seconds between polls while waiting for owner
WAIT_TIMEOUT = 60.0    # seconds before a waiter gives up (409)
STALE_AFTER = 120.0    # a 'processing' row older than this may be taken over

SCHEMA = """
CREATE TABLE IF NOT EXISTS payments (
    id              TEXT PRIMARY KEY,
    idempotency_key TEXT NOT NULL UNIQUE,
    amount          REAL NOT NULL,
    currency        TEXT NOT NULL,
    created_at      TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS idempotency_keys (
    key             TEXT PRIMARY KEY,
    body_hash       TEXT NOT NULL,
    status          TEXT NOT NULL,             -- 'processing' | 'completed'
    response_status INTEGER,
    response_body   TEXT,
    updated_at      REAL NOT NULL
);
"""


def get_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(db_path(), timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA busy_timeout=30000")
    return conn


@app.on_event("startup")
def init_db() -> None:
    conn = get_conn()
    try:
        conn.executescript(SCHEMA)
        conn.commit()
    finally:
        conn.close()


@app.get("/health")
def health() -> dict:
    return {"ok": True}


def conflict() -> JSONResponse:
    return JSONResponse(
        status_code=422,
        content={"error": {"code": "idempotency_conflict"}},
    )


def replay(row: sqlite3.Row) -> JSONResponse:
    return JSONResponse(
        status_code=row["response_status"],
        content=json.loads(row["response_body"]),
        headers={"Idempotent-Replay": "true"},
    )


@app.post("/payments")
async def create_payment(request: Request) -> JSONResponse:
    raw = await request.body()
    idem_key = request.headers.get("Idempotency-Key")
    if not idem_key:
        return JSONResponse(
            status_code=400,
            content={"error": {"code": "missing_idempotency_key"}},
        )
    try:
        canonical = json.dumps(json.loads(raw), sort_keys=True)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return JSONResponse(
            status_code=400,
            content={"error": {"code": "invalid_json"}},
        )
    body_hash = hashlib.sha256(canonical.encode()).hexdigest()

    # --- Claim the idempotency key -------------------------------------
    conn = get_conn()
    try:
        while True:
            try:
                conn.execute(
                    "INSERT INTO idempotency_keys "
                    "(key, body_hash, status, updated_at) VALUES (?, ?, 'processing', ?)",
                    (idem_key, body_hash, time.time()),
                )
                conn.commit()
                break  # we are the owner
            except sqlite3.IntegrityError:
                row = conn.execute(
                    "SELECT * FROM idempotency_keys WHERE key = ?", (idem_key,)
                ).fetchone()
                if row is None:
                    continue  # transient; retry insert

                if row["body_hash"] != body_hash:
                    return conflict()

                if row["status"] == "completed":
                    return replay(row)

                # Owner still processing: wait-and-replay.
                deadline = time.time() + WAIT_TIMEOUT
                while time.time() < deadline:
                    time.sleep(POLL_INTERVAL)
                    row = conn.execute(
                        "SELECT * FROM idempotency_keys WHERE key = ?", (idem_key,)
                    ).fetchone()
                    if row is None:
                        break  # stale takeover happened; go claim it again
                    if row["body_hash"] != body_hash:
                        return conflict()
                    if row["status"] == "completed":
                        return replay(row)

                # Stale 'processing' row (owner died): take over once.
                fresh = conn.execute(
                    "UPDATE idempotency_keys SET status='processing', updated_at=? "
                    "WHERE key=? AND status='processing' AND updated_at < ?",
                    (time.time(), idem_key, time.time() - STALE_AFTER),
                )
                conn.commit()
                if fresh.rowcount == 0 and time.time() >= deadline:
                    return JSONResponse(
                        status_code=409,
                        content={"error": {"code": "request_in_progress"}},
                    )

        # --- We own the key: execute exactly once ----------------------
        payment_id = str(uuid.uuid4())
        try:
            conn.execute(
                "INSERT INTO payments (id, idempotency_key, amount, currency, created_at) "
                "VALUES (?, ?, ?, ?, ?)",
                (
                    payment_id,
                    idem_key,
                    float(request_state_amount := json.loads(canonical)["amount"]),
                    json.loads(canonical)["currency"],
                    time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                ),
            )
        except sqlite3.IntegrityError:
            # UNIQUE(idempotency_key) hit: someone else already paid under
            # this key. Fall back to replaying whatever is stored.
            row = conn.execute(
                "SELECT * FROM idempotency_keys WHERE key = ?", (idem_key,)
            ).fetchone()
            if row and row["status"] == "completed":
                return replay(row)
            raise

        response_body = {
            "payment_id": payment_id,
            "amount": request_state_amount,
            "currency": json.loads(canonical)["currency"],
            "idempotency_key": idem_key,
            "status": "succeeded",
        }
        payload = json.dumps(response_body)
        conn.execute(
            "UPDATE idempotency_keys SET status='completed', "
            "response_status=?, response_body=?, updated_at=? WHERE key=?",
            (201, payload, time.time(), idem_key),
        )
        conn.commit()
        return JSONResponse(status_code=201, content=response_body)
    finally:
        conn.close()
"})
